var builder = WebApplication.CreateBuilder(args);

// Dev secrets generated by compose (secrets-init) are files named like SeedAdmin__Password (ADR-0012).
builder.Configuration.AddKeyPerFile("/run/secrets/dev", optional: true, reloadOnChange: false);

var settings = builder.Configuration.GetSection("App").Get<AppSettings>() ?? new AppSettings();

builder.Services
    .AddBuildingBlocks(builder.Configuration)
    .AddApplication(settings)
    .AddInfrastructure(builder.Configuration)
    .AddFastEndpoints(o => o.Assemblies = [typeof(Program).Assembly, typeof(DemoApi.Application.DependencyInjection).Assembly]);

var app = builder.Build();
app.UseBuildingBlocks();
await app.RunAsync();

/// <summary>Entry point; public for WebApplicationFactory in integration tests.</summary>
public partial class Program;